BEGIN TRY
  BEGIN TRANSACTION;

  UPDATE dbo.Accounts SET Balance = Balance - @Amount WHERE AccountId = @FromId;
  UPDATE dbo.Accounts SET Balance = Balance + @Amount WHERE AccountId = @ToId;

  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

CREATE OR ALTER PROCEDURE dbo.GetCustomerOrders
  @CustomerId int
AS
BEGIN
  SET NOCOUNT ON;

  SELECT OrderId, CreatedAt, TotalAmount
  FROM dbo.Orders
  WHERE CustomerId = @CustomerId
  ORDER BY CreatedAt DESC;
END;

SET STATISTICS IO, TIME ON;

SELECT OrderId, TotalAmount
FROM dbo.Orders
WHERE CustomerId = @CustomerId;

SET STATISTICS IO, TIME OFF;
